def f(g):
    import numpy as np
    a=np.array(g); h,w=a.shape; out=a.copy()
    for y in range(h):
        for x in range(w):
            v=a[y,x]; nb=[]
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=y+dy,x+dx
                if 0<=ny<h and 0<=nx<w: nb.append(a[ny,nx])
            if v not in nb:
                from collections import Counter
                out[y,x]=Counter(nb).most_common(1)[0][0]
